/**
 * Sorts an array of integers in ascending order using Bubble Sort algorithm.
 * Input constraints: array length <= 100, integers between -10,000 and 10,000.
 *
 * Algorithm explanation:
 * - Bubble Sort repeatedly steps through the list, compares adjacent elements,
 *   and swaps them if they are in the wrong order. The pass through the list is
 *   repeated until the list is sorted.
 * - The algorithm gets its name because smaller elements "bubble" to the top
 *   (beginning) of the list.
 *
 * Time complexity: O(n^2) in the worst and average case, O(n) in the best case
 * (when the array is already sorted and the optimized version with a flag is used).
 * Space complexity: O(1) as it sorts in place.
 *
 * @param {Array<number>} arr - The array to be sorted.
 * @returns {Array<number>} The sorted array (the original array is sorted in place).
 * @throws {Error} If input validation fails.
 */
function bubbleSort(arr) {
  // --- Input validation ---
  if (!Array.isArray(arr)) {
    throw new Error('Input must be an array.');
  }
  if (arr.length > 100) {
    throw new Error('Array length must not exceed 100.');
  }
  for (let i = 0; i < arr.length; i++) {
    if (!Number.isInteger(arr[i])) {
      throw new Error(`Array element at index ${i} is not an integer.`);
    }
    if (arr[i] < -10000 || arr[i] > 10000) {
      throw new Error(`Array element at index ${i} is out of range [-10000, 10000].`);
    }
  }

  // --- Bubble Sort implementation ---
  const n = arr.length;
  let swapped;  // Flag to detect if any swap occurred in a pass

  // Outer loop: each pass places the largest unsorted element at the end
  for (let i = 0; i < n - 1; i++) {
    swapped = false;

    // Inner loop: compare adjacent elements up to the last unsorted position
    for (let j = 0; j < n - 1 - i; j++) {
      if (arr[j] > arr[j + 1]) {
        // Swap the two elements
        const temp = arr[j];
        arr[j] = arr[j + 1];
        arr[j + 1] = temp;
        swapped = true;
      }
    }

    // If no swaps occurred, the array is already sorted; exit early
    if (!swapped) break;
  }

  return arr;
}
